function syncDecor(){colliders=colliders.filter(b=>!dynamicDecor.includes(b.owner));dynamicDecor.forEach(g=>root.remove(g));dynamicDecor=[];let spots={lantern:[3,-2],rug:[0,4],books:[8,-8],plant:[7,1],harp:[-7,1]};state.placed.forEach(id=>{let p=spots[id];if(p)dynamicDecor.push(decorModel(id,...p))});}
