function setLighting(){let night=state.minutes>1080||state.minutes<360;scene3.background=new THREE.Color(room?'#14272b':night?'#182839':weather!=='clear'?(weather==='snow'?'#b3c6ce':'#647d80'):'#b8ccc6');skyDome.visible=!room;skyClouds.visible=!room;skyDome.material.map=skyTextures[weather!=='clear'?'weather':night?'night':'day'];skyClouds.children.forEach(c=>c.children.forEach(p=>{p.material.opacity=night?.08:weather==='clear'?.35:.5;}));scene3.fog=room?null:new THREE.Fog(scene3.background,weather==='clear'?(night?100:140):65,weather==='clear'?(night?600:850):380);ambient.intensity=room?1.8:night?.75:2;sun.intensity=room?1.5:night?.8:3.1;sun.color.set(night?'#a9c7e2':'#ffe0b5');lamps.forEach(m=>{if(m.material.emissive)m.material.emissiveIntensity=room||night?1.8:.4});}
