for(let z of [-169,-69,31,131]){let p1=mapProject(-150,z,w,h),p2=mapProject(z===-169?50:150,z,w,h);ct.strokeStyle='#699ea0';ct.lineWidth=big?13:8;ct.beginPath();ct.moveTo(p1.x,p1.y);ct.lineTo(p2.x,p2.y);ct.stroke();ct.strokeStyle='#bdd8ca';ct.lineWidth=1;ct.stroke();}
