function overviewCameraTarget(){let altitude=Math.max(430,380/Math.max(.4,camera.aspect)/.9);return new THREE.Vector3(0,altitude,altitude*.472-48);}
function toggleOverview(){if(room){speak('Templar','Step outside to see the entire kingdom in 3D. Your live map still shows every district while you are indoors.');return}overview=!overview;firstPerson=false;$('overviewMode').classList.toggle('active',overview);$('overviewMode').textContent=overview?'⌖ Return to ground':'⌖ Whole World View';$('cameraMode').textContent='◉ Follow view';if(!overview)setLighting();toast(overview?'The entire kingdom is visible. Click a building or path to walk there.':'Back beside Templar. Open Map whenever you need directions.');}
$('overviewMode').onclick=toggleOverview;$('centerMap').onclick=toggleOverview;
function updateWaypoint(){if(!worldDestination){waypoint.hidden=true;return}let p=room?returnPosition:player.group.position;if(!p)return;let distance=Math.hypot(p.x-worldDestination.x,p.z-worldDestination.z);if(distance<2){worldDestination=null;waypoint.hidden=true;toast('You have reached your destination');return}waypoint.hidden=false;waypoint.textContent=worldDestination.name+' · '+Math.ceil(distance)+' steps away';}
