function showNavigationTrail(){if(navigationTrail){navigationTrail.parent?.remove(navigationTrail);navigationTrail.geometry.dispose();navigationTrail.material.dispose();navigationTrail=null;}if(room||!route.length)return;let points=[player.group.position.clone().setY(.12),...route.map(p=>p.clone().setY(.12))];navigationTrail=new THREE.Line(new THREE.BufferGeometry().setFromPoints(points),new THREE.LineDashedMaterial({color:'#f6db86',dashSize:1.1,gapSize:.7,transparent:true,opacity:.85}));navigationTrail.computeLineDistances();root.add(navigationTrail);}
