$('zoomIn').onclick=()=>adjustZoom(-3);$('zoomOut').onclick=()=>adjustZoom(3);$('focusPlayer').onclick=()=>{focusPlayer();toast('Camera follows you closely. Use + and − to adjust.');};$('zoomSlider').oninput=e=>{let value=Number(e.target.value);if(overview||firstPerson)focusPlayer();zoom=Math.max(8,Math.min(room?28:45,value));};
