// Chapter II adds action-based discoveries without changing the original case.
state.witnessQuest??={stage:'available',observed:0,rewarded:false};state.friendships??={};
const witnessStages={available:'Speak with Archivist Rowan inside the Royal Archive to begin.',follow:'Follow Courier Sable from the capital toward the manor’s back lane. Stay nearby; she will wait if you fall behind.',listen:'Stay near Sable and Bram in the back lane to overhear their conversation.',letter:'Search the loose paving stone beside the tree in the manor’s back lane.',verify:'Take Nessa’s letter to Lady Mirelle inside Silverstitch Manor.',seal:'Compare the letter’s silver seal with the original elf tools inside the workshop.',complete:'Nessa’s testimony is preserved. Sable is recognized as a witness protector, and the family’s history has a new verified record.'};
let courier=null,courierPath=[],courierProgress=0,contact=null,hiddenStone=null,lastLifeTick=0;
function ensureLifeState(){if(!state.witnessQuest||typeof state.witnessQuest!=='object'||!witnessStages[state.witnessQuest.stage])state.witnessQuest={stage:'available',observed:0,rewarded:false};if(!Number.isFinite(state.witnessQuest.observed))state.witnessQuest.observed=0;state.friendships??={};}
function npcDialogue(n){ensureLifeState();let friendship=state.friendships[n.name]||0;state.friendships[n.name]=friendship+1;
if(n.name==='Lady Mirelle'&&state.witnessQuest.stage==='verify'){advanceWitness('seal');return 'That is Nessa’s handwriting. The silver seal matches our family’s pattern. Please compare it with the original elf’s tools at the shoemaker’s workshop; then no one can dismiss her testimony.';}
if(n.name==='Lady Mirelle'&&state.witnessQuest.stage==='complete')return 'Nessa’s letter is protected now. You looked beyond appearances and found the people keeping her words safe. Our family remembers that.';
if(n.name==='Lady Mirelle'&&state.solved)return 'My children are home. We remember your kindness, Templar. Their years apart cannot be erased, but they can choose what comes next.';
if(n.name==='Archivist Rowan'&&roomKind==='archive'&&state.witnessQuest.stage==='available'){advanceWitness('follow');return 'A courier named Sable has been carrying a witness’s letter through the capital. Follow her toward the manor’s back lane. Find out who she is meeting before you decide whom to trust.';}
if(n.name==='Liora'&&state.crafted)return 'The boots you made are carrying me through every woodland journey. I remember who helped me, Templar.';
if(n.name==='Master Cobble'&&state.witnessQuest.stage==='seal')return 'The chest of original tools carries our ancestor’s silver seal. Open it and compare the pattern with Nessa’s letter.';
let activity=n.activity||'visiting';if(friendship>2)return 'Good to see you again, Templar. '+(n.words||'You are always welcome here.');return (n.words||'Welcome to Eldoria.')+(!room?' I am '+activity+' right now.':'');}
function advanceWitness(stage){state.witnessQuest.stage=stage;state.witnessQuest.observed=0;persist();toast('The Witness’s Hidden Letter · '+({follow:'Follow Sable',listen:'Listen in the back lane',letter:'Find the hidden letter',verify:'Visit Lady Mirelle',seal:'Compare the silver seal',complete:'Testimony preserved'}[stage]||stage));}
function setupWitnessWorld(){if(!worldCache)return;const exterior=worldCache.root,saveRoot=root;root=exterior;let saveNpcs=npcs,saveObjects=objects;npcs=worldCache.npcs;objects=worldCache.objects;
courier=npc('Courier Sable',2,5,'#735f87','I carry letters for people who cannot safely deliver them themselves.');courier.isCourier=true;courier.offset={x:0,z:0};contact=npc('Bram the Record Keeper',33,-19,'#7b8071','Not every secret is a crime. Some secrets keep people safe.');contact.isContact=true;contact.offset={x:0,z:0};let chest=furniture('chest',32,-23);chest.scale.set(.55,.22,.65);hiddenStone=interactable('Examine the loose paving stone',32,-22,()=>{let stage=state.witnessQuest.stage;if(stage==='letter'){advanceWitness('verify');modal('Nessa’s hidden letter','<p>“They changed our names, but I remember the eight silver stitches. The festival carriage took us to Thornmere. I kept a record of the households and the payments, so the truth could survive even if I could not return myself.”</p><p>A small silver seal is pressed into the fold. Take the letter to Lady Mirelle.</p>');}else if(['verify','seal','complete'].includes(stage))speak('Templar','The letter is already safe in my journal.');else speak('Templar','A loose stone beside an old tree. Someone may be using this place to hide something.');},chest,2.5);tree(37,-23,1.1,'oak');
let o=worldCache.objects.find(o=>o.node===courier.group);if(o)o.action=()=>speak('Courier Sable',state.witnessQuest.stage==='follow'?'Keep a little distance, traveler. I am meeting someone who can protect a witness’s words.':'Mistress Vey’s people wanted this letter destroyed. We kept it safe.');
if(state.solved){let survivor=npc('Nessa Silverstitch',23,7,'#9f7899','I am choosing what comes next for my own life. Thank you for helping our names return.');survivor.offset={x:0,z:0};}root=saveRoot;npcs=saveNpcs;objects=saveObjects;updateWitnessActors();}
function updateWitnessActors(){if(!courier)return;let stage=state.witnessQuest.stage,active=!['available','complete'].includes(stage);courier.group.visible=active;contact.group.visible=active;if(['listen','letter','verify','seal'].includes(stage)){courier.group.position.set(30,0,-18);contact.group.position.set(33,0,-19);}hiddenStone.node.visible=true;}
function tickWitness(dt){if(!courier||room)return;let quest=state.witnessQuest,p=player.group.position;updateWitnessActors();if(quest.stage==='follow'){
if(!courierPath.length&&courierProgress===0)courierPath=findRoute(courier.group.position,{x:30,z:-18});let distance=p.distanceTo(courier.group.position);if(distance<18&&distance>2&&courierPath.length){let next=courierPath[0],direction=next.clone().sub(courier.group.position);if(direction.length()<dt*2.3){courier.group.position.copy(next);courierPath.shift();}else{direction.normalize();courier.group.position.addScaledVector(direction,dt*2.3);courier.group.rotation.y=Math.atan2(direction.x,direction.z);}courierProgress++;animatePerson(courier,elapsed,true);if(distance<14)quest.observed+=dt;}if(!courierPath.length&&courierProgress>0&&quest.observed>=4){advanceWitness('listen');speak('Sable & Bram','Sable: “The witnesses must be protected.” Bram: “Then leave her letter beneath the loose stone. The Silverstitches will know the seal.”');}}
else if(quest.stage==='listen'&&Math.hypot(p.x-31,p.z+18)<11){quest.observed+=dt;if(quest.observed>=4){advanceWitness('letter');speak('Templar','They are protecting a witness, not hiding a crime. The loose stone should be nearby.');}}
let o=worldCache.objects.find(o=>o.node===courier.group);if(o){o.x=courier.group.position.x;o.z=courier.group.position.z;}}
function scheduleFor(n,hour){let base=n.origin,offset=n.offset||{x:0,z:0};if(hour>=6&&hour<10)return {x:base.x+5,z:16,activity:'getting breakfast',visible:true};if(hour>=10&&hour<17)return {x:base.x,z:base.z,activity:n.name.includes('Professor')?'teaching at the academy':n.name==='Liora'?'preparing woodland deliveries':'working in the district',visible:true};if(hour>=17&&hour<22)return {x:0,z:12,activity:'meeting neighbors after work',visible:true};let doors=worldCache?.objects.filter(o=>o.type==='door'&&o.district===Object.keys(districtPositions).find(id=>districtPositions[id][0]===offset.x&&districtPositions[id][1]===offset.z))||[];let door=doors.sort((a,b)=>Math.hypot(a.x-offset.x-base.x,a.z-offset.z-base.z)-Math.hypot(b.x-offset.x-base.x,b.z-offset.z-base.z))[0];return{x:door?door.x-offset.x:base.x,z:door?door.z-offset.z:base.z,activity:'resting at home',visible:false};}
function animateResident(n,i,dt){if(n.isCourier||n.isContact){if(n.isContact)animatePerson(n,elapsed+i,false);return;}let pos=n.group.position,moving=false;if(!room){let schedule=scheduleFor(n,Math.floor(state.minutes/60));n.activity=schedule.activity;let targetKey=schedule.x+','+schedule.z;if(n.scheduleKey!==targetKey){n.scheduleKey=targetKey;let offset=n.offset||{x:0,z:0};n.dayRoute=findRoute(new THREE.Vector3(pos.x+offset.x,0,pos.z+offset.z),{x:schedule.x+offset.x,z:schedule.z+offset.z});}
if(n.dayRoute?.length){let offset=n.offset||{x:0,z:0},world=pos.clone().add(new THREE.Vector3(offset.x,0,offset.z)),next=n.dayRoute[0],dir=next.clone().sub(world),step=dt*1.4;if(dir.length()<step){pos.set(next.x-offset.x,0,next.z-offset.z);n.dayRoute.shift();}else{dir.normalize();pos.addScaledVector(dir,step);n.group.rotation.y=Math.atan2(dir.x,dir.z);moving=true;}}n.group.visible=schedule.visible||!!n.dayRoute?.length;
}else{n.group.visible=true;n.group.rotation.y=Math.atan2(player.group.position.x-pos.x,player.group.position.z-pos.z);}animatePerson(n,elapsed+i,moving);if(!room)n.group.position.y=bridgeHeight(pos.x+(n.offset?.x||0),pos.z+(n.offset?.z||0));let o=objects.find(o=>o.node===n.group);if(o){o.x=pos.x+(n.offset?.x||0);o.z=pos.z+(n.offset?.z||0);}}
const renderBeforeLife=renderUI;renderUI=function(){ensureLifeState();renderBeforeLife();let q=state.witnessQuest;$('quest').insertAdjacentHTML('beforeend',`<div class="card"><small>THE WITNESS’S HIDDEN LETTER</small><p>${witnessStages[q.stage]||witnessStages.available}</p><span class="pill">${q.stage==='complete'?'Testimony preserved':'Playable witness investigation'}</span><button id="questGo_witness">Take me there →</button></div>`);};
const journalBeforeLife=journal;journal=function(){journalBeforeLife();let q=state.witnessQuest;if(['verify','seal','complete'].includes(q.stage))$('modal').insertAdjacentHTML('beforeend','<div class="card"><h3>Nessa’s hidden letter</h3><p>Eight silver stitches, altered names, the carriage to Thornmere, and a record of the households and their payments. The folded letter bears the original elf’s silver seal.</p><p>'+(q.stage==='complete'?'The handwriting and seal have both been verified. The archive preserves this testimony.':'Verification is still in progress.')+'</p></div>');};$('journal').onclick=()=>journal();

const loadBeforeLife=loadRoom;loadRoom=function(kind,name){loadBeforeLife(kind,name);if(kind==='craft'||kind==='orders'){let original=objects.find(o=>o.name.includes('original tools'));if(original){let before=original.action;original.action=()=>{if(state.witnessQuest.stage==='seal'){advanceWitness('complete');if(!state.witnessQuest.rewarded){state.witnessQuest.rewarded=true;awardAdventureCoins(75,'The witness investigation');persist();}modal('The testimony survives','<p>The eight silver stitches match. Nessa’s letter becomes a verified record of what happened at Briar House.</p><p>Sable and Bram were protecting evidence. Lady Mirelle sends her gratitude, and the royal archive preserves the testimony where it cannot be quietly erased.</p><p>Witness investigation complete · +75 mooncoins.</p>');}else before();};}}};

// Hands-on life, persistent possessions, and nine family journeys.
function ensureImmersion(){state.life??={bag:{moonleaf:3,honey:2,flour:3},outfit:'Twilight',hair:'Chestnut',skin:'Warm',family:{},events:{},furniture:{},drawer:false};let l=state.life;l.bag??={};l.family??={};l.events??={};l.furniture??={};return l;}
let spawnedEvents=new Set(),seated=false,sleeping=false,sleepTimer=null,sleepWakeMinutes=null,carried=null,lastAmbient=0,lastEvent=0,cinemaUntil=0;
const outfits={Twilight:'#465c8d',Moss:'#58784f',Rose:'#9e607f',Ember:'#ae7045'},skins={Warm:'#ddb394',Deep:'#86543f',Porcelain:'#e9ccb6'},hairs={Chestnut:'#422b29',Silver:'#ccd0ce',Gold:'#c5a05b'};
function applyStyle(){let l=ensureImmersion();player.group.traverse(m=>{if(!m.isMesh)return;let hex=m.material.color?.getHexString();if(Object.values(outfits).some(c=>c.slice(1)===hex))m.material=mat(outfits[l.outfit]||outfits.Twilight);if(Object.values(skins).some(c=>c.slice(1)===hex))m.material=mat(skins[l.skin]||skins.Warm);if(Object.values(hairs).some(c=>c.slice(1)===hex))m.material=mat(hairs[l.hair]||hairs.Chestnut);});}
function addBag(id,n=1){let b=ensureImmersion().bag;b[id]=(b[id]||0)+n;persist();}
function useBag(id,n=1){let b=ensureImmersion().bag;if((b[id]||0)<n)return false;b[id]-=n;persist();return true;}
function carryItem(id){if(carried){player.group.remove(carried);carried.geometry.dispose();carried=null;}if(!id)return;carried=new THREE.Mesh(new THREE.BoxGeometry(.32,.4,.2),mat(id==='lantern'?'#ffd482':'#bfa879'));carried.position.set(.58,1.1,.4);player.group.add(carried);}
function satchel(){let l=ensureImmersion();modal('Your satchel & style','<p>Carry supplies, eat what you cook, equip a light, and choose your appearance.</p>');for(let [id,n] of Object.entries(l.bag).filter(([,n])=>n>0)){action(id+' × '+n,()=>{if(id==='woodland bread'){useBag(id);advanceRealmTime(20);toast('Warm bread shared with the world. A restful pause.');}else{carryItem(id);toast('Carrying '+id);}satchel();});}for(let id of state.inventory)action('Equip '+id,()=>{carryItem(id);$('modal').close();});action('Put carried item away',()=>carryItem(null));for(let [key,choices]of Object.entries({outfit:outfits,hair:hairs,skin:skins}))for(let name of Object.keys(choices))action(key+': '+name+(l[key]===name?' ✓':''),()=>{l[key]=name;applyStyle();persist();satchel();});action('Friendships',()=>{modal('People who remember you','<p>Conversations and home visits build familiarity.</p>'+Object.entries(state.friendships).map(([n,v])=>'<p>'+n+' · '+(v>=5?'Friend':v>=2?'Acquaintance':'New connection')+'</p>').join(''));});}
$('satchel').onclick=satchel;
function cinema(title,words){cinemaUntil=elapsed+7;$('cinemaCaption').textContent=title+' · '+words;$('cinemaCaption').hidden=false;document.body.classList.add('cinematic');speak(title,words);}
let cap=document.createElement('div');cap.id='cinemaCaption';cap.hidden=true;canvas.parentElement.append(cap);
function cook(){let l=ensureImmersion();modal('Bake woodland bread','<p>Mix flour, honey, and moonleaf, then tend the oven. Finished bread goes into your satchel.</p>');if(!['flour','honey','moonleaf'].every(id=>(l.bag[id]||0)>0)){action('Buy pantry refill · 8 coins',()=>{if(state.coins<8){toast('You need 8 mooncoins');return;}state.coins-=8;for(let id of ['flour','honey','moonleaf'])addBag(id,2);cook();});return;}action('Mix the ingredients',()=>{modal('Tend the oven','<p>The dough is ready. Choose gentle heat to keep the honey from burning.</p>');action('Gentle hearth heat',()=>{for(let id of ['flour','honey','moonleaf'])useBag(id);addBag('woodland bread',2);$('modal').close();cinema('Fresh from the hearth','Two warm loaves are in your satchel.');});action('Roaring flames',()=>toast('Too hot for honey dough. Try gentle heat.'));});}
function moveFurniture(o){modal('Move '+o.name,'<p>Move one step at a time. Open paths and doors stay clear.</p>');for(let [name,dx,dz]of [['Left',-1,0],['Right',1,0],['Forward',0,-1],['Back',0,1]])action(name,()=>{let b=colliders.find(b=>b.owner===o.node);if(!b)return;let x=b.x+dx,z=b.z+dz;if(Math.abs(x)+b.w>10.7||Math.abs(z)+b.d>9||Math.hypot(x,z-9.4)<4||colliders.some(c=>c!==b&&Math.abs(x-c.x)<b.w+c.w+.6&&Math.abs(z-c.z)<b.d+c.d+.6)){toast('Leave room around the furniture and doorway');return;}let ox=b.x,oz=b.z;b.x=x;b.z=z;if(objects.some(a=>a!==o&&!findRoute(player.group.position,{x:a.x,z:a.z}).length)){b.x=ox;b.z=oz;toast('That would block another activity');return;}o.node.position.x+=dx;o.node.position.z+=dz;o.x+=dx;o.z+=dz;ensureImmersion().furniture[o.name]={x,z};persist();moveFurniture(o);});}
