if(['home','tavern'].includes(kind))roomObject('Cook at the hearth','bottle',9,5,cook);
if(kind==='home'){let drawer=furniture('chest',8,3);interactable('Open the pantry drawer',8,4.7,()=>{drawer.children[1].rotation.x=-.65;let l=ensureImmersion();if(!l.drawer){l.drawer=true;addBag('moonleaf',2);addBag('flour',2);speak('Templar','Moonleaf and flour—packed into my satchel.');}else speak('Templar','The drawer is open. The supplies are already in your satchel.');},drawer,2.5);for(let o of [...objects].filter(o=>o.node?.userData.bounds&&o.name.includes('decorations'))){let move={...o,name:'Writing desk',x:o.x,action:()=>moveFurniture(move)};objects.push(move);}let welcome=objects.find(o=>o.name==='Invite Pip for tea');if(welcome)welcome.action=()=>{modal('Invite a friend for tea','<p>Your guests remember your hospitality.</p>');for(let guest of ['Pip','Fern','Liora'])action('Invite '+guest,()=>{if(!state.visitors.includes(guest)){state.visitors.push(guest);npc(guest,-4+state.visitors.indexOf(guest)*3,4,'#b29476','Thank you for making room for me.');state.friendships[guest]=(state.friendships[guest]||0)+1;}persist();$('modal').close();cinema('Tea with '+guest,'Stories, warm bread, and time together.');});};for(let guest of state.visitors.filter(n=>n!=='Pip'))npc(guest,-4+state.visitors.indexOf(guest)*3,4,'#b29476','It feels good to be welcome.');}
if(kind==='home'){for(let [name,pos]of Object.entries(ensureImmersion().furniture)){let o=objects.find(o=>o.name===name),b=o&&colliders.find(b=>b.owner===o.node);if(o&&b){let dx=pos.x-b.x,dz=pos.z-b.z;o.node.position.x+=dx;o.node.position.z+=dz;o.x+=dx;o.z+=dz;b.x=pos.x;b.z=pos.z;}}}for(let [i,t]of familyTasks.entries())if(t[0]===kind)roomObject('Find the '+t[1],'chest',-3,6,()=>{let l=ensureImmersion(),stage=l.family[t[3]]||'new';if(stage==='new'){l.family[t[3]]='found';addBag(t[1]);carryItem(t[1]);cinema('House '+t[3],'An heirloom found. Take it to the family’s ancestral room.');}else speak('Templar','This family heirloom is already in my care.');});
