const ancestralBeforeHands=loadAncestral;loadAncestral=function(f){ancestralBeforeHands(f);let task=familyTasks.find(t=>t[3]===f[0]);roomObject(task[2],'table',5,0,()=>{let l=ensureImmersion();if(l.family[f[0]]==='complete'){speak('House '+f[0],'Your restored heirloom is part of our story now.');return;}if(l.family[f[0]]!=='found'){speak('House '+f[0],'Find our '+task[1]+' in '+task[0]+' before beginning the restoration.');return;}modal(task[2],'<p>Use the heirloom carefully, then add a personal blessing to preserve the family’s story.</p>');action('Restore it with care',()=>{useBag(task[1]);l.family[f[0]]='complete';awardAdventureCoins(25,'Family heirloom restored');addBag(f[0]+' keepsake');persist();$('modal').close();carryItem(null);cinema('House '+f[0],'A restored heirloom, a keepsake, and 25 mooncoins.');});});};
const beforeJournalHands=journal;journal=function(){beforeJournalHands();$('modal').insertAdjacentHTML('beforeend','<h3>Family adventures</h3>'+familyTasks.map(t=>'<p>House '+t[3]+' · '+(ensureImmersion().family[t[3]]||'Find '+t[1]+' in '+t[0])+ '</p>').join(''));};
function surpriseEvent(){if(room||$('modal').open)return;let key=zone,events=ensureImmersion().events;if(events[key]||spawnedEvents.has(key))return;spawnedEvents.add(key);let [x,z]=districtPositions[zone];let g=furniture('chest',x+9,z+17);interactable('Help with a surprise delivery',x+9,z+18.8,()=>{if(g.userData.claimed){speak('Templar','The delivery is safely completed.');return;}g.userData.claimed=true;events[key]=true;addBag('moonleaf',2);awardAdventureCoins(10,'A neighbor’s surprise delivery');persist();cinema('An unexpected delivery','You saved a neighbor’s supplies from the rain. +10 coins and moonleaf.');},g,2.5);persist();speak('A passing neighbor','My delivery slipped off the cart! There is a parcel beside the path. Could you help?');}
function playEffect(freq,duration=.12,type='sine',volume=.018){if(!sound||!audio)return;let o=audio.createOscillator(),v=audio.createGain();o.type=type;o.frequency.value=freq;v.gain.setValueAtTime(volume,audio.currentTime);v.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(v);v.connect(audio.destination);o.start();o.stop(audio.currentTime+duration);}
function startBedRest(){if(sleeping||transitioning||storyScene)return;if(seated)standUp();stopTravel();$('modal').close();sleeping=true;sleepWakeMinutes=540;player.group.position.set(-8,1.45,-4);player.group.rotation.set(-Math.PI/2,0,0);animatePerson(player,elapsed,false);focusPlayer();speak('Templar','Settling into bed for a quiet rest. Move to wake early.');sleepTimer=setTimeout(()=>wakeFromBed(),4500);}
function wakeFromBed(announce=true){if(!sleeping)return;clearTimeout(sleepTimer);sleepTimer=null;sleeping=false;player.group.rotation.set(0,0,0);player.group.position.set(-5.5,0,-4);animatePerson(player,elapsed,false);if(Number.isFinite(sleepWakeMinutes))setRealmTime(sleepWakeMinutes);sleepWakeMinutes=null;persist();setLighting();if(announce){announceRealmMorning();speak('Templar','Day '+(state.day||1)+'. Rested and ready. Your adventures continue where you left them.');}}
function standUp(){if(!seated)return;seated=false;player.group.position.set(4,0,6.6);animatePerson(player,elapsed,false);}
function tickImmersion(dt,moving){if(moving&&seated)standUp();if(moving&&elapsed-lastAmbient>.35){lastAmbient=elapsed;playEffect(footstepFrequency(),.08,'triangle',.015);}else if(!moving&&elapsed-lastAmbient>5){lastAmbient=elapsed;playEffect(room?280:weather==='snow'?700:weather==='sleet'?180:weather==='rain'?110:1200,.3,weather==='rain'||weather==='sleet'?'sawtooth':'sine',.012);}if(elapsed-lastEvent>90){lastEvent=elapsed;surpriseEvent();}if(cinemaUntil&&elapsed>cinemaUntil){cinemaUntil=0;$('cinemaCaption').hidden=true;document.body.classList.remove('cinematic');}}
