function safeQuestPosition(x,z){if(!blocked(x,z))return new THREE.Vector3(x,0,z);for(let r=1;r<=4;r+=.5)for(let a=0;a<Math.PI*2;a+=Math.PI/8){let xx=x+Math.cos(a)*r,zz=z+Math.sin(a)*r;if(!blocked(xx,zz)&&(!room||Math.abs(xx)<10.5&&zz>-9.5&&zz<9.5))return new THREE.Vector3(xx,0,zz);}return null;}
