let endlessParcel=null,endlessPickup=null,endlessSteward=null;
function endlessState(){let q=state.endlessAdventure;if(!q||!Number.isSafeInteger(q.completed)||q.completed<0)q=state.endlessAdventure={completed:0,stage:'collect'};if(!['collect','deliver'].includes(q.stage))q.stage='collect';return q;}
function endlessMission(){let q=endlessState(),ids=Object.keys(districtPositions),district=ids[(q.completed*7+2)%ids.length],theme=endlessThemes[Math.floor(q.completed/ids.length)%endlessThemes.length];return {district,theme,number:q.completed+1,reward:12+q.completed%5*3};}
function syncEndlessParcel(){if(!endlessParcel)return;let q=endlessState(),m=endlessMission(),[x,z]=districtPositions[m.district];let xx=x-30,zz=z+20;
 // Resolve against exterior collisions even while visiting an interior.
 const previous=colliders,previousRoom=room;colliders=worldCache.colliders;room=null;let pos=safeQuestPosition(xx,zz);colliders=previous;room=previousRoom;if(!pos)pos=new THREE.Vector3(x-30,0,z+10);endlessParcel.position.copy(pos);endlessParcel.visible=q.stage==='collect';endlessPickup.x=pos.x;endlessPickup.z=pos.z;endlessPickup.name='Collect '+m.theme[1];}
