function deliverEndlessParcel(){if(roomKind!=='home'){speak('Steward Lyra','Your cottage is now our dispatch point. Go home and turn in your parcel at the adventure board.');return;}let q=endlessState();if(q.stage!=='deliver'){speak('Steward Lyra',endlessMission().theme[2]+' Open Your adventure for directions. There is always another neighbor to help.');return;}let m=endlessMission();awardAdventureCoins(m.reward,'Kingdom parcel delivered');q.completed++;q.stage='collect';persist();syncEndlessParcel();renderUI();speak('Steward Lyra','Thank you! You earned '+m.reward+' mooncoins. Your next errand is ready: '+endlessMission().theme[0]+'. Stay as long as you like.');}
