function owlBook(index=0,page=0){stopTaleNarration();let tale=aurelinTales[index];state.owlStories??=[];if(!state.owlStories.includes(index))state.owlStories.push(index);persist();modal('Aurelin · '+tale.title,'<small>THE CHERISHED KEEPER OF THE MEMORYBOUGH</small><p>'+tale.pages[page]+'</p><p>Page '+(page+1)+' of '+tale.pages.length+'</p>');if(page>0)action('← Previous page',()=>owlBook(index,page-1));if(page<tale.pages.length-1)action('Continue the tale →',()=>owlBook(index,page+1));else action('Choose another tale',owlLibrary);taleAudioControls(tale.pages[page],'owl');action('Return to the kingdom',()=>{stopTaleNarration();$('modal').close();});}
function owlLibrary(){stopTaleNarration();modal('Aurelin’s living fairy tales','<p>Citizens cherish Aurelin as the keeper of their shared memory. Beneath the Memorybough, every ending can become another beginning. Choose a tale.</p>');aurelinTales.forEach((t,i)=>action(t.title,()=>owlBook(i,0)));action('Leave a kind thought at the tree',()=>{state.owlBlessings=(state.owlBlessings||0)+1;persist();$('modal').close();speak('Aurelin','Your kindness is welcome here, Templar. May your next chapter be one you are proud to tell.');});action('Return to the kingdom',()=>$('modal').close());}
