function adornAurelin(parent,x=0,y=0,z=0){let attire=new THREE.Group();attire.position.set(x,y,z);parent.add(attire);attire.name='Aurelin’s gold spectacles and scholar regalia';for(let side of [-1,1]){let rim=new THREE.Mesh(new THREE.TorusGeometry(.165,.018,8,24),mat('#e4c575',{metalness:.65,roughness:.25}));rim.position.set(side*.18,1.15,.445);attire.add(rim);let brow=box(attire,side*.18,1.37,.34,.21,.04,.045,'#f0e4d6');brow.rotation.z=-side*.1;}box(attire,0,1.15,.445,.075,.026,.026,'#e4c575');cyl(attire,0,.53,-.11,.4,.5,.55,'#54476b',12);sphere(attire,0,.75,.37,.065,'#e4c575');let medal=cyl(attire,0,.51,.41,.095,.095,.04,'#e8ca7f',12);medal.rotation.x=Math.PI/2;return attire;}


