function communityState(){state.community??={completed:0,step:0,clues:[],history:[]};state.community.clues??=[];state.community.history??=[];state.farms??={};state.animalCare??={};state.citizenMemories??={};return state.community;}
function communityJob(){let q=communityState();return communityJobs[q.completed%communityJobs.length];}
function completeCommunity(choice='helped',expected=communityState().completed){let q=communityState();if(q.completed!==expected)return;let job=communityJob(),reward=20+q.completed%4*5;q.history.push({title:job[0],choice});q.history=q.history.slice(-30);q.completed++;q.step=0;q.clues=[];delete q.harePosition;awardAdventureCoins(reward,'Community or festival activity');if(choice==='returned privately')state.friendships['Nola']=(state.friendships.Nola||0)+2;else if(choice==='reported honestly')state.friendships['Guard Alder']=(state.friendships['Guard Alder']||0)+2;persist();syncCommunity();renderUI();$('modal').close();cinema('A kingdom shaped by you',job[0]+' completed · '+reward+' mooncoins. Your next adventure is ready.');}
function communityActivity(){let q=communityState(),index=q.completed%5,token=q.completed;if(index===0){modal('Mend the noticeboard','<p>The supporting beam has split. The notices are damp, but their messages can still be saved. Choose how to repair it.</p>');action('Brace the beam with sound wood',()=>{q.step=1;persist();modal('Finish the repair','<p>The brace is secure. What should protect the notices?</p>');action('Fit a sloping rain cover',()=>completeCommunity('repaired with a rain cover',token));action('Paste them over the cracked wood',()=>toast('The wood still needs protection from rain.'));});action('Cover the split with paint',()=>toast('Paint will not strengthen a broken beam.'));}
 else if(index===1){if(q.step===0){q.step=1;persist();syncCommunity();$('modal').close();speak('Sanctuary keeper','The little hare trusts you now. Walk slowly back to the sanctuary garden at the marked station. Stay close so it can follow.');}else speak('Sanctuary keeper','Bring the hare within a few steps of this station. It follows while you remain nearby.');}
 else if(index===2){modal('The missing market seal','<p>A merchant’s seal vanished during unloading. Examine all three accounts before deciding what happened.</p>'+q.clues.map(key=>'<p><strong>'+key+':</strong> '+({footprints:'Muddy footprints go to a sheltered bench and back.',witness:'An apprentice sheltered a wet package from the rain.',receipt:'The receipt lists the seal among items awaiting collection.'}[key])+'</p>').join(''));for(let [key,text]of [['footprints','Small muddy footprints lead from the cart toward the sheltered bench, then return.'],['witness','A young apprentice moved a wet package under cover during the rain.'],['receipt','The package receipt lists the seal among items awaiting collection.']])action('Examine '+key,()=>{if(!q.clues.includes(key))q.clues.push(key);persist();speak('Evidence',text);communityActivity();});if(q.clues.length===3){action('Return it privately to the apprentice',()=>completeCommunity('returned privately',token));action('Give an honest account to the guard',()=>completeCommunity('reported honestly',token));action('Accuse the apprentice of theft',()=>toast('The evidence shows sheltering a package, not theft.'));}}
 else if(index===3){modal('A harvest for the village kitchen','<p>Grow moonleaf in a garden bed, then bring two sprigs from your satchel. The kitchen will use them for supper.</p>');action('Contribute two moonleaf sprigs',()=>{if(!useBag('moonleaf',2)){toast('You need two moonleaf sprigs. Grow them in a garden bed or buy them at the market.');return;}completeCommunity('shared the harvest',token);});}
 else startLanternMusic();}
function startLanternMusic(){let token=communityState().completed,beat=0,pattern=['Moon','Star','Leaf','Star','Moon'];function show(){modal('The lantern musicians','<p>Repeat the melody: <strong>'+pattern.join(' · ')+'</strong></p><p>Notes played: '+beat+' / '+pattern.length+'</p>');for(let [i,n]of ['Moon','Star','Leaf'].entries())action(n,()=>{if(communityState().completed!==token)return;playEffect([523,659,784][i],.18,'sine',.025);if(n!==pattern[beat]){beat=0;toast('Try that melody again.');show();return;}beat++;if(beat===pattern.length)completeCommunity('performed at the lantern gathering',token);else show();});}show();}
function syncCommunity(){let index=communityState().completed%5;for(let s of communityStations)s.node.visible=s.index===index;if(lostHare){lostHare.visible=index===1;if(index===1){let saved=communityState().harePosition;lostHare.position.set(saved?.x??-31,0,saved?.z??123);let o=worldCache.objects.find(o=>o.node===lostHare);if(o){o.x=lostHare.position.x;o.z=lostHare.position.z;}}}lostHareRoute=[];}
