function headquarters(){state.headquarters??={pending:[],history:[],accepted:{}};const h=state.headquarters;h.pending??=[];h.history??=[];h.accepted??={};return h;}
window.deferAdventureReward=(amount,title)=>{let h=headquarters();h.pending.push({amount,title:title==='Adventure progress'?(h.active||title):title});toast('Reward recorded · return home to collect '+amount+' mooncoins.');};
function claimHomeRewards(){if(roomKind!=='home'){toast('Go home to collect your adventure rewards.');return;}let h=headquarters(),valid=h.pending.filter(r=>Number.isFinite(r.amount)&&r.amount>0),total=valid.reduce((n,r)=>n+r.amount,0);if(!total){toast('No rewards waiting yet. Choose an adventure from your board.');return;}h.pending=[];h.history.push(...valid.map(r=>({...r,returnedAt:Date.now()})));h.history=h.history.slice(-60);state.coins+=total;persist();toast('Welcome back! Collected '+total+' mooncoins at home.');homeAdventureBoard();}
