if(/^(Grow and harvest|Plant and harvest)/i.test(label))return null;if(label==='Restore it with care'){let task=familyTasks.find(t=>room?.includes(t[3]));if(task)return physicalProfile(task[2])||'inspect';}if(/^(Talk to|Speak to|Read |Hear |Listen|Stop narration|Return home|Go home|Choose|Continue|Next|Previous|Back|Leave|Visit|Show|Take me|Start|Turn in|Review|Stay|Live in|outfit:|hair:|skin:)/i.test(label))return null;
 if(/^Lantern, water flask/.test(label))return 'trade';if(label==='Silent moss soles')return 'boot';if(label==='Loose arrow')return 'archery';if(/^(Moon|Star|Leaf)$/.test(label))return 'music';if(/^(Seed|Tree|Fruit)$/.test(label))return 'rune';
 if(/Plant|waking seed/i.test(label))return 'plant';if(/Water the|rose water|preserved rose/i.test(label))return 'water';if(/Harvest|Gather.*herb/i.test(label))return 'harvest';if(/Brace|Fit a sloping|Cover the split|Paste them/i.test(label))return 'repair';if(/Polish|glass rose/i.test(label))return 'polish';if(/Weave|ribbon of light/i.test(label))return 'weave';if(/Balance|giant coin/i.test(label))return 'balance';if(/three bowls/i.test(label))return 'bowls';if(/Stitch|Mend|traveling cloak|Restore it with care/i.test(label))return 'stitch';
 if(/Feed|Care for the/i.test(label))return 'feed';if(/Greet gently/i.test(label))return 'pet';if(/Share woodland|Contribute|Return it privately/i.test(label))return 'share';if(/Light a lantern/i.test(label))return 'lantern';if(/Invite (Pip|Fern|Liora)$|Invite .*tea|Enjoy a free supper|Order supper/i.test(label))return 'meal';if(/Examine|Inspect [123]|Check the|Find the|Search the|Collect.*parcel|Open the pantry/i.test(label))return /parcel/i.test(label)?'parcel':'inspect';
