function renderPhysicalActivity(){let a=physicalActivity;if(!a)return;for(let i=objects.length-1;i>=0;i--)if(a.interactions.includes(objects[i]))objects.splice(i,1);a.interactions=[];a.group.traverse(n=>{delete n.userData.interaction;});let node=a.parts[Math.min(a.step,a.parts.length-1)]||a.group;if(a.plot!==undefined&&a.profile==='plant')a.parts.slice(1).forEach(n=>n.visible=false);node.visible=true;let o=physicalInteractionBefore(a.spec.steps[a.step],player.group.position.x,player.group.position.z-1.5,()=>playEasyActivity(),node,6);a.interactions.push(o);workPanel.innerHTML='';let title=document.createElement('strong');title.textContent=a.spec.title;let p=document.createElement('p');p.textContent=a.manual?gestureInstruction(gestureMode(a))+' · '+a.spec.steps[a.step]:'Click or tap the highlighted object, press E, or use the button below.';workPanel.append(title,p);a.parts.forEach(n=>n.traverse(m=>{if(m.isMesh){m.userData.workColor??=m.material.color.getHex();m.material=mat('#'+m.userData.workColor.toString(16).padStart(6,'0'),{emissive:'#000000'});}}));let target=a.parts[Math.min(a.step,a.parts.length-1)];target?.traverse(m=>{if(m.isMesh)m.material=mat('#'+m.userData.workColor.toString(16).padStart(6,'0'),{emissive:'#aa7933',emissiveIntensity:.45});});let meter=document.createElement('p');meter.id='gestureMeter';meter.textContent=a.manual?'Hold the object to begin · release when finished':a.assisted?'Working…':a.spec.steps[a.step];workPanel.append(meter);if(!a.manual)workButton(a.plot!==undefined?({plant:'Plant seeds',water:'Water this plot',harvest:'Harvest plants'})[a.profile]:'Use · '+a.spec.steps[a.step],playEasyActivity);workButton(a.manual?'Easy controls':'More hands-on controls',()=>{if(a.motion>0||a.assisted)return;a.manual=!a.manual;renderPhysicalActivity();});let ring=gestureReceiver(a);ring.visible=!!a.manual;equipWorkTool(a,gestureMode(a));workButton('Cancel activity',()=>cancelPhysicalActivity(true));}
function performPhysicalStep(index){let a=physicalActivity;if(!a||a.finished||a.motion>0)return;if(index!==a.step){toast('Follow the glowing object first.');return;}a.step++;a.motion=a.profile==='fishing'?[1,1.7,1.2][a.step-1]:.6;let part=a.parts[Math.min(index,a.parts.length-1)];if(part){if(a.profile==='chest'&&index===1){a.lid.rotation.x=-.8;}if(a.profile==='plant'&&a.plot!==undefined&&index===0){a.soil.position.y=.17;sphere(a.group,0,.3,0,.15,'#3f3022',1,.2,1);}if(a.profile==='harvest')part.visible=false;else if(a.profile==='plant'&&index>0){if(a.plot!==undefined){part.visible=false;a.soil.material=mat(index===2?'#805f40':'#563e2b');}else a.parts[index].visible=true;}else if(a.profile==='water')part.rotation.z+=.35;else if(a.profile==='balance')part.rotation.z=0;else if(a.profile==='feed'||a.profile==='pet')a.parts[0].position.z+=.12;else if(a.profile==='lantern')a.group.position.y+=.45;else if(['stitch','weave'].includes(a.profile))part.material=mat('#e4c776');else if(a.profile==='music'){part.rotation.z=.1;playEffect(({Moon:523,Star:659,Leaf:784})[a.label]||659,.25,'sine',.025);}else if(a.plot===undefined&&a.profile!=='fishing')part.rotation.y+=.2;}if(a.profile==='fishing'&&a.step===1)playEffect(240,.18,'sine',.025);if(a.profile==='fishing'&&a.step===3)playEffect(540,.15,'triangle',.035);if(a.profile==='archery'&&a.step===3)archeryReleaseTime=Date.now();if(a.profile==='catch'&&part)part.visible=false;if(a.step===a.spec.steps.length)a.finishing=true;else renderPhysicalActivity();}
