var workGesture;
function gestureMode(a){const modes={boot:['trace','place','trace','place'],archery:['draw','aim','pluck'],plant:['rub','place','rub'],water:['place','pour','place'],harvest:['pluck','pluck','place'],repair:['place','rub','rub','place'],polish:['rub','rub','rub'],stitch:['place','trace','trace','pluck'],weave:['place','trace','pluck'],feed:['place','place','hold'],pet:['hold','rub','hold'],records:['pluck','inspect','stamp'],inspect:['inspect','inspect','trace'],council:['pluck','trace','stamp'],rewards:['place','trace','place'],chest:['pluck','pluck','place'],music:['pluck'],meal:['place','pour','hold'],lantern:['place','rub','pluck']};return modes[a.profile]?.[a.step]||'place';}
function gestureInstruction(mode){return ({draw:'Pull the bowstring to the right, then release',aim:'Drag the arrow toward the target ring',hold:'Hold gently for two seconds',inspect:'Hold and turn the evidence back and forth',stamp:'Press and hold the seal for one second',trace:'Hold and follow the seam from left to right',pour:'Drag sideways to tilt, then hold for two seconds',rub:'Hold and work back and forth four times',pluck:'Hold and pull the glowing object, then release',place:'Drag the glowing object into the green receiving ring'})[mode];}
function prepareGestureIngredient(name){let w=handsOnWork;if(!w||w.phase!=='ingredients')return;if(w.prepared)w.group.remove(w.prepared);let n=sphere(w.group,-.85,1.35,.3,.17,name==='Moonleaf'?'#6aaf72':name==='Honey'?'#dfb74f':'#eee4cb');n.userData.ingredient=name;w.prepared=n;toast('Drag the prepared ingredient into the bowl.');}
function gestureTarget(owner){if(owner===handsOnWork)return owner.phase==='ingredients'?owner.prepared:owner.mixture;return owner.parts[Math.min(owner.step,owner.parts.length-1)];}
function gestureReceiver(owner){if(owner.plot!==undefined){if(!owner.receiver){let ring=new THREE.Mesh(new THREE.TorusGeometry(.25,.025,8,32),mat('#80e8ac',{emissive:'#57b77b',emissiveIntensity:.5}));ring.rotation.x=Math.PI/2;ring.position.set(0,.35,0);owner.group.add(ring);owner.receiver=ring;}return owner.receiver;}if(owner===handsOnWork)return owner.phase==='ready'?owner.oven:owner.bowl;if(!owner.receiver){let n=new THREE.Mesh(new THREE.TorusGeometry(.3,.025,8,32),mat('#80e8ac',{emissive:'#57b77b',emissiveIntensity:.5}));n.rotation.x=Math.PI/2;if(owner.profile==='archery')n.position.set(0,1.1,-3.85);else if(['feed','pet'].includes(owner.profile))n.position.set(-.35,.18,.5);else n.position.set(.85,1,.55);owner.group.add(n);owner.receiver=n;}return owner.receiver;}
function gestureScreen(node){let p=node.getWorldPosition(new THREE.Vector3()).project(camera),r=canvas.getBoundingClientRect();return {x:r.left+(p.x+1)*r.width/2,y:r.top+(1-p.y)*r.height/2};}
function gestureProgress(g,x,y,now){let dx=x-g.x,dy=y-g.y;g.distance+=Math.hypot(dx,dy);if(Math.abs(dx)>3){let sign=Math.sign(dx);if(g.sign&&sign!==g.sign&&g.sweep>18){g.turns++;g.sweep=0;}g.sign=sign;g.sweep+=Math.abs(dx);}let angle=Math.atan2(y-g.center.y,x-g.center.x),delta=Math.atan2(Math.sin(angle-g.angle),Math.cos(angle-g.angle));if(Math.hypot(x-g.center.x,y-g.center.y)>12&&Math.abs(delta)<.7)g.circle+=Math.abs(delta);g.angle=angle;g.x=x;g.y=y;if(g.mode==='pour'){if(Math.abs(x-g.startX)>28){g.tiltSince??=now;}else g.tiltSince=null;g.progress=g.tiltSince?Math.min(1,(now-g.tiltSince)/2000):0;}else if(['hold','stamp'].includes(g.mode)){g.heldSince??=now;g.progress=Math.min(1,(now-g.heldSince)/(g.mode==='stamp'?1000:2000));}else if(g.mode==='rub'||g.mode==='inspect')g.progress=Math.min(1,g.turns/4);else if(g.mode==='mix')g.progress=Math.min(1,g.circle/(Math.PI*2));else if(g.mode==='trace'){let t=(x-g.startX)/110;if(Math.abs(y-g.startY)>25)g.failed=true;g.progress=g.failed?0:Math.max(0,Math.min(1,t));}else if(g.mode==='draw')g.progress=Math.min(1,Math.max(0,(x-g.startX)/65));else g.progress=Math.min(1,g.distance/50);return g.progress;}
function gestureRelease(g,x,y){if(g.owner!==(physicalActivity||handsOnWork))return false;let complete=g.progress>=1;if(g.mode==='place'||g.mode==='aim'){let dest=gestureScreen(gestureReceiver(g.owner));complete=Math.hypot(x-dest.x,y-dest.y)<55;}g.node.position.copy(g.original);g.node.rotation.z=g.rotation;g.node.scale.y=1;if(!complete){toast('Keep working: '+(g.mode==='place'?'drop inside the green ring.':gestureInstruction(g.mode)));return false;}if(g.owner===handsOnWork){let w=g.owner;if(w.phase==='ingredients'){let name=g.node.userData.ingredient;w.group.remove(g.node);w.prepared=null;workIngredient(name);}else if(w.phase==='ready')heatHandsOnWork();else workStroke();}else performPhysicalStep(g.owner.step);return true;}
canvas.addEventListener('pointerdown',e=>{let owner=physicalActivity||handsOnWork;if(!owner||e.button!==0)return;e.stopImmediatePropagation();let node=gestureTarget(owner);if(!node||owner.motion>0||owner.finishing||owner.finished)return;owner.group.updateMatrixWorld(true);camera.updateMatrixWorld(true);canvasPoint(e);let hits=raycaster.intersectObject(node,true);if(!owner.manual&&owner.plot!==undefined&&!hits.length)hits=raycaster.intersectObject(farmBed(owner.plot),true);if(!hits.length){toast('Tap the highlighted object or use the activity button.');return;}if(!owner.manual){if(owner===handsOnWork)playEasyWork();else playEasyActivity();return;}let mode=owner===handsOnWork?(owner.phase==='mix'?'mix':owner.phase==='knead'?'rub':'place'):gestureMode(owner);gestureReceiver(owner);let center=gestureScreen(node);let normal=camera.getWorldDirection(new THREE.Vector3());let plane=new THREE.Plane().setFromNormalAndCoplanarPoint(normal,node.getWorldPosition(new THREE.Vector3()));let grab=raycaster.ray.intersectPlane(plane,new THREE.Vector3());workGesture={owner,node,mode,plane,grab,x:e.clientX,y:e.clientY,startX:e.clientX,startY:e.clientY,center,angle:Math.atan2(e.clientY-center.y,e.clientX-center.x),circle:0,distance:0,turns:0,sweep:0,sign:0,heldSince:Date.now(),progress:0,original:node.position.clone(),rotation:node.rotation.z};if(mode==='trace'){let guide=document.createElement('div');guide.id='seamGuide';Object.assign(guide.style,{position:'fixed',left:e.clientX+'px',top:e.clientY+'px',width:'110px',height:'2px',background:'#ffdf83',boxShadow:'0 0 8px #ffe4a4',pointerEvents:'none',zIndex:'20'});canvas.parentElement.append(guide);}canvas.setPointerCapture(e.pointerId);canvas.style.cursor='grabbing';},true);
canvas.addEventListener('pointermove',e=>{if(!workGesture)return;e.stopImmediatePropagation();let g=workGesture;if(g.owner!==(physicalActivity||handsOnWork)){workGesture=null;return;}gestureProgress(g,e.clientX,e.clientY,Date.now());let dx=(e.clientX-g.startX)/100,dy=(e.clientY-g.startY)/100;if(['place','pluck','draw','aim'].includes(g.mode)){canvasPoint(e);let hit=raycaster.ray.intersectPlane(g.plane,new THREE.Vector3());if(hit&&g.grab){let world=g.node.parent.localToWorld(g.original.clone()).add(hit.sub(g.grab));g.node.position.copy(g.node.parent.worldToLocal(world));}}else if(g.mode==='pour')g.node.rotation.z=g.rotation+Math.max(-1,Math.min(1,dx));else if(g.mode==='inspect')g.node.rotation.y+=dx*.03;else if(g.mode==='mix')g.node.rotation.y+=.1;else g.node.scale.y=1-Math.min(.3,Math.abs(dy)*.2);if(g.owner.profile==='plant'&&g.owner.soil){g.owner.soil.position.y=.24-g.progress*.08;g.owner.soil.material.color.set('#58432d');}player.arms.forEach((arm,i)=>{arm.rotation.x=-1.15+dy*.2;arm.rotation.z=(i?-.2:.2)+dx*.15;});let meter=document.getElementById('gestureMeter');if(meter)meter.textContent=Math.round(g.progress*100)+'% complete';},true);
canvas.addEventListener('pointerup',e=>{if(!workGesture){if(physicalActivity||handsOnWork)e.stopImmediatePropagation();return;}e.stopImmediatePropagation();let g=workGesture;workGesture=null;document.getElementById('seamGuide')?.remove?.();if(['pour','hold','stamp'].includes(g.mode))gestureProgress(g,e.clientX,e.clientY,Date.now());gestureRelease(g,e.clientX,e.clientY);canvas.style.cursor='default';player.arms.forEach(a=>a.rotation.z=0);},true);
