function syncFarmPlot(index){let bed=farmBed(index);if(!bed)return;let f=state.farms?.[index]||{stage:'empty'};bed.scale.y=1;let crop=bed.userData.crop,definition=farmCrop(f),cropId=f.crop||'moonleaf';if(crop&&bed.userData.cropId!==cropId){bed.remove(crop);crop.traverse(n=>{if(n.isMesh)n.geometry.dispose();});crop=null;}if(!crop){for(let n of bed.children.slice(5))n.visible=false;crop=new THREE.Group();bed.add(crop);bed.userData.crop=crop;bed.userData.cropId=cropId;for(let i=0;i<4;i++){let stem=new THREE.Group();stem.position.set(i%2?1.2:-1.2,0,i<2?-.6:.6);crop.add(stem);buildGardenPlant(stem,definition);}}if(!bed.userData.sown){let sown=new THREE.Group();bed.add(sown);bed.userData.sown=sown;for(let i=0;i<4;i++)sphere(sown,(i-1.5)*(typeof index==='string'?.65:1.4),.32,0,.16,'#886a47',1,.4,1);}bed.userData.sown.visible=f.stage==='planted';crop.visible=['growing','ready'].includes(f.stage)&&!(physicalActivity?.plot===index&&physicalActivity.profile==='harvest');let progress=f.stage==='ready'?1:f.stage==='growing'?Math.max(0,Math.min(1,1-(f.readyAt-Date.now())/(farmCrop(f).seconds*1000))):0;crop.scale.set(typeof index==='string'?.5:1,.2+progress*.8,typeof index==='string'?.65:1);crop.traverse(n=>{if(n.userData.ripeProduce)n.visible=progress>=.75;});let soil=bed.children[0];soil.material.color.set(f.stage==='growing'?'#4c3c29':'#66513b');}
