const indoorFarmLoadBefore=loadRoom;loadRoom=function(kind,name){selectedGardenPlot=null;indoorGardenBeds={};indoorFarmLoadBefore(kind,name);if(kind!=='garden')return;for(let node of [...root.children].filter(n=>n.userData.gardenTime)){root.remove(node);node.geometry?.dispose();}state.farms??={};for(let i=0;i<6;i++){let id='conservatory:'+i,bed=new THREE.Group();bed.position.set((i%3-1)*6,0,-6+Math.floor(i/3)*6);root.add(bed);box(bed,0,.23,0,3,.1,3,'#66513b');for(let side of [-1,1]){box(bed,side*1.5,.3,0,.12,.35,3.1,'#ad946f');box(bed,0,.3,side*1.5,3.1,.35,.12,'#ad946f');}indoorGardenBeds[id]=bed;if(!state.farms[id]&&state.garden[i])state.farms[id]={stage:'growing',readyAt:state.garden[i].time+60000};syncFarmPlot(id);interactable('Work garden plot '+(i+1),bed.position.x,bed.position.z+2,()=>farmMenu(id),bed,2.8);}persist();};
const directGardenBefore=garden;garden=function(){if(roomKind!=='garden'){directGardenBefore();return;}modal('Your hands-on conservatory','<p>Choose a plot or click its soil. Dig, plant, cover, water and harvest at that bed. Every crop has its own growing time after watering.</p>');for(let i=0;i<6;i++){let id='conservatory:'+i;action('Work garden plot '+(i+1)+' · '+(state.farms[id]?.stage||'empty'),()=>farmMenu(id));}};
