function updateProximityLabels(){root.updateMatrixWorld(true);root.traverse(n=>{if(!n.isSprite||!(n.userData.buildingLabel||n.userData.proximityLabel))return;let interaction=n.userData.interaction;let distance;if(n.userData.buildingLabel&&interaction&&interaction.type!=='npc')distance=Math.hypot(player.group.position.x-interaction.x,player.group.position.z-interaction.z);else{n.parent.getWorldPosition(labelAnchor);distance=Math.hypot(player.group.position.x-labelAnchor.x,player.group.position.z-labelAnchor.z);}n.visible=!overview&&distance<=(n.userData.buildingLabel?10:6);});}

