function ensureWoodlandWaterfall(){if(!worldCache||worldCache.waterfall)return;let g=new THREE.Group();g.name='Whispering Cascade';g.position.set(-175,-.12,-69);worldCache.root.add(g);worldCache.waterfall=g;buildNaturalMountain(worldCache.root,-194,-93,0,.7);buildNaturalMountain(worldCache.root,-194,-45,3,.7);worldCache.colliders.push({x:-194,z:-93,w:16.8,d:16.8},{x:-194,z:-45,w:16.8,d:16.8});woodlandWaterfall={group:g,ribbons:[],foam:[]};
 // The outlet lies inside the existing forest river channel, joining its water level.
 for(let i=0;i<11;i++){let rock=canopy(g,-4-(i%3)*1.1,1.8+i*.8,(i%2?1:-1)*(1.7+i%3*.4),2.3,['#87918b','#a1a69a','#707e76'][i%3],1,.9,1.1);rock.userData.waterfallRock=true;}
 canopy(g,-3,11.5,0,3,'#87918b',1,1,1.15);box(g,-1.4,13.5,0,3,.08,5,'#8bc5ce',{normalMap:riverNormalTex,transparent:true,opacity:.6,roughness:.12});let streamTexture=riverNormalTex.clone();streamTexture.repeat.set(2,8);woodlandWaterfall.texture=streamTexture;
 for(let i=0;i<9;i++){let ribbon=box(g,-.3+i*.065,6.8,(i-4)*.58,.12,13.6,.66,'#a5d8de',{normalMap:streamTexture,normalScale:new THREE.Vector2(.6,.6),transparent:true,opacity:.48,roughness:.12,metalness:.08});woodlandWaterfall.ribbons.push(ribbon);}
 let pool=box(g,1.1,.015,0,6,.075,6.5,'#70b4be',{normalMap:riverNormalTex,transparent:true,opacity:.55,roughness:.12});pool.userData.waterfallOutlet={x:-148,z:-69,riverLevel:-.12};let outlet=box(g,15,.025,0,28,.07,6.5,'#70b4be',{normalMap:riverNormalTex,transparent:true,opacity:.62,roughness:.12});outlet.userData.waterfallChannel={startX:-174,endX:-146,z:-69};woodlandWaterfall.channel=outlet;box(g,15,-.3,0,28,.1,7.2,'#727d65',{map:groundTex});for(let side of [-1,1]){let bank=box(worldCache.root,-171,-.4,-69+side*9,46,.7,12,'#718463',{map:groundTex,roughness:1});bank.userData.waterfallBank=true;}
 for(let i=0;i<14;i++){let foam=canopy(g,.2+i%4*.55,.1,(i%7-3)*.55,.26,'#deefec',1.8,.15,1);foam.material=mat('#deefec',{transparent:true,opacity:.6,roughness:.6});woodlandWaterfall.foam.push(foam);}
 let positions=[];for(let i=0;i<140;i++)positions.push((i%5)*.1,1+(i%29)*.46,(i%17-8)*.32);let spray=new THREE.Points(new THREE.BufferGeometry().setAttribute('position',new THREE.Float32BufferAttribute(positions,3)),new THREE.PointsMaterial({color:'#d7f2ef',size:.09,transparent:true,opacity:.65,depthWrite:false}));g.add(spray);woodlandWaterfall.spray=spray;
 worldCache.colliders.push({x:-179,z:-69,w:3,d:3.8});
}
