 ['Garden soup',['carrots','potatoes','onions'],2],['Roasted harvest',['pumpkins','corn','rosemary'],2],['Elven salad',['lettuce','tomatoes','peas','basil'],2],['Strawberry tart',['strawberries','wheat','honey'],2],['Blueberry apple pie',['blueberries','apples','flour'],2],['Mint tea',['mint','honey'],2],['Lavender tea',['lavender','honey'],2],['Silverberry preserves',['silverberries','honey'],2],['Starlight mushroom stew',['starlight mushrooms','moonleaf'],2],['Sunflower seed loaf',['sunflowers','wheat','flour'],2],['Grilled river fish',['@fish','rosemary'],1],['Fish and vegetables',['@fish','carrots','potatoes'],2]
