function resolveRecipeIngredients(recipe){return recipe[1].map(id=>id==='@fish'?riverFishSpecies.map(f=>f[0].toLowerCase()).find(id=>(ensureImmersion().bag[id]||0)>0)||'river trout':id);}
function makeHarvestRecipe(recipe){let ingredients=resolveRecipeIngredients(recipe),bag=ensureImmersion().bag;if(!ingredients.every(id=>(bag[id]||0)>=1)){toast('Needs '+ingredients.join(', '));return;}startCommandActivity('kitchen',()=>{let current=ensureImmersion().bag;if(!ingredients.every(id=>(current[id]||0)>=1)){toast('Those ingredients are no longer in your satchel.');return;}for(let id of ingredients)current[id]--;let dish=recipe[0].toLowerCase();current[dish]=(current[dish]||0)+recipe[2];state.cookedMeals=(state.cookedMeals||0)+1;persist();toast(recipe[2]+' '+dish+' added to your satchel');harvestKitchen();},recipe[0]);}
function harvestKitchen(){modal('Harvest kitchen','<p>Turn your garden harvest and river catches into meals. One click starts visible preparation, stirring, cooking and serving. Ingredients are used only when the dish is finished.</p>');realmMenuButton('Bake original woodland bread',()=>startHandsOnWork('bread'));for(let recipe of harvestRecipes){let ingredients=resolveRecipeIngredients(recipe),button=realmMenuButton('Cook '+recipe[0],()=>makeHarvestRecipe(recipe));let ready=ingredients.every(id=>(ensureImmersion().bag[id]||0)>0);button.disabled=!ready;$('modal').insertAdjacentHTML('beforeend','<small>'+ingredients.join(' + ')+' → '+recipe[2]+' servings'+(ready?'':' · gather ingredients first')+'</small><br>');}}
function harvestTrade(){modal('Sell your harvest','<p>Sell one crop or caught fish at a time for three mooncoins. Keep ingredients for cooking and flowers for your cottage.</p>');let bag=ensureImmersion().bag,ids=[...Object.values(farmCrops).map(c=>c.item),...riverFishSpecies.map(f=>f[0].toLowerCase())];for(let id of ids)if((bag[id]||0)>0)realmMenuButton('Sell '+id+' · 3 coins',()=>{if((ensureImmersion().bag[id]||0)<1)return;startCommandActivity('trade',()=>{let b=ensureImmersion().bag;if((b[id]||0)<1)return;b[id]--;state.coins+=3;state.harvestSales=(state.harvestSales||0)+1;persist();renderUI();harvestTrade();},id);});if(!ids.some(id=>(bag[id]||0)>0))$('modal').insertAdjacentHTML('beforeend','<p>Your satchel has no produce to sell yet. Plant a crop or visit a fishing spot.</p>');}
