 for(let side of [-1,1]){box(root,side*11.45,.6,0,.09,1.1,21,'#78674f',{map:floorTex});box(root,side*11.37,1.2,0,.12,.1,21,'#c1b191');}let cupboardSpot=null;for(let [cx,cz]of [[-10,8],[-10,0],[-10,-8],[10,0],[10,-8],[10,8]]){if(colliders.some(b=>Math.abs(cx-b.x)<b.w+1.2&&Math.abs(cz-b.z)<b.d+1))continue;let prospective={x:cx,z:cz,w:.75,d:.5};colliders.push(prospective);let approach={x:cx+(cx<0?2:-2),z:cz};let clear=findRoute(player.group.position,approach).length&&objects.filter(o=>o.type!=='npc').every(o=>findRoute(player.group.position,{x:o.x,z:o.z}).length);colliders.pop();if(clear){cupboardSpot=[cx,cz];break;}}if(!cupboardSpot)return;let [cupboardX,cupboardZ]=cupboardSpot;let cabinet=new THREE.Group();cabinet.position.set(cupboardX,0,cupboardZ);root.add(cabinet);box(cabinet,0,1.3,0,1.4,2.6,.8,'#79634b');box(cabinet,0,1.3,.42,1.2,2.3,.05,'#3c473d');for(let y of [.5,1.3,2.1]){box(cabinet,0,y,.42,1.2,.07,.7,'#b19a73');for(let x of [-.32,.32])cyl(cabinet,x,y+.16,.35,.09,.11,.25,'#c2b69a',12);}let hinge=new THREE.Group();hinge.position.set(-.65,0,.5);cabinet.add(hinge);box(hinge,.65,1.3,0,1.3,2.4,.07,'#a18b69',{map:floorTex});sphere(hinge,1.13,1.3,.09,.04,'#d2bd89');cabinet.userData.cupboard=true;colliders.push({x:cupboardX,z:cupboardZ,w:.75,d:.5,owner:cabinet});interactable('Open or close the room cupboard',cupboardX+(cupboardX<0?2:-2),cupboardZ,()=>{hinge.userData.open=!hinge.userData.open;hinge.userData.target=hinge.userData.open?-1.7:0;toast(hinge.userData.open?'Cupboard open · neatly stocked shelves':'Cupboard closed');},cabinet,3);interiorAccents.push(hinge);
