function footstepFrequency(){if(room)return 140;if(bridgeHeight(player.group.position.x,player.group.position.z)>.2)return 210;let nearRoad=kingdomPathCovered(player.group.position.x,player.group.position.z)||Object.values(districtPositions).some(([x,z])=>Math.abs(player.group.position.z-z-10)<3||Math.abs(player.group.position.x-x-40)<3);return nearRoad?105:70;}
let realmAmbience=null,ambientZoneClock=0;
function tickRealmAmbience(dt){if(!sound||!audio){if(realmAmbience)realmAmbience.gain.gain.value=0;return;}if(!realmAmbience&&typeof audio.createBuffer==='function'&&typeof audio.createBiquadFilter==='function'){let buffer=audio.createBuffer(1,audio.sampleRate*2,audio.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=(Math.random()*2-1)*.5;let source=audio.createBufferSource(),filter=audio.createBiquadFilter(),gain=audio.createGain();source.buffer=buffer;source.loop=true;filter.type='lowpass';filter.frequency.value=1200;source.connect(filter);filter.connect(gain);gain.connect(audio.destination);gain.gain.value=0;source.start();realmAmbience={source,filter,gain};}if(realmAmbience){let p=player.group.position,riverDistance=Math.min(...Object.values(districtPositions).map(([x,z])=>Math.abs(p.z-z-31))),cascadeDistance=Math.hypot(p.x+49,p.z+69),hearth=room&&lamps.some(m=>m.userData.hearthFlame),volume=room?(hearth?.012:0):weather==='rain'?.028:Math.max(0,.022*(1-riverDistance/14),.065*(1-cascadeDistance/35));realmAmbience.gain.gain.value=volume;realmAmbience.filter.frequency.value=hearth?550:cascadeDistance<35?1900:1100;}
 ambientZoneClock+=dt;if(ambientZoneClock>3){ambientZoneClock=0;if(room&&lamps.some(m=>m.userData.hearthFlame))playEffect(130,.08,'triangle',.007);else if(zone==='market'&&!room&&state.minutes>=360&&state.minutes<1200&&Math.floor(elapsed/3)%5===0&&typeof window.SpeechSynthesisUtterance==='function'&&window.speechSynthesis&&!window.speechSynthesis.speaking&&!window.speechSynthesis.pending&&!storyScene&&!physicalActivity&&!handsOnWork){let lines=['Fresh bread from the hearth!','Herbs and flowers, gathered this morning.','Lovely weather for the market.','Thank you, neighbor. Enjoy your day.'],utterance=new window.SpeechSynthesisUtterance(lines[Math.floor(elapsed/15)%lines.length]);utterance.lang='en-US';utterance.volume=.12;utterance.rate=.9;window.speechSynthesis.speak(utterance);}}}
