function enjoyHarvestMeal(){modal('Enjoy your cooking','<p>Sit with a warm meal or cup of tea. Your character sets the table, serves and enjoys it.</p>');let bag=ensureImmersion().bag,foods=['woodland bread',...harvestRecipes.map(r=>r[0].toLowerCase())];for(let id of foods)if((bag[id]||0)>0)realmMenuButton('Enjoy '+id,()=>startCommandActivity('meal',()=>{let bag=ensureImmersion().bag;if((bag[id]||0)<1)return;bag[id]--;state.mealsEnjoyed=(state.mealsEnjoyed||0)+1;advanceRealmTime(15);persist();toast('A quiet moment with '+id);$('modal').close();},id));if(!foods.some(id=>(bag[id]||0)>0))$('modal').insertAdjacentHTML('beforeend','<p>Cook a dish first, then enjoy it here.</p>');}

