function upgradeAnimalAppearance(animal){let node=animal.node;if(node.userData.elvenAnimal)return;node.userData.elvenAnimal=true;let type=animal.type,color=type==='deer'?'#b79d7e':type==='cat'?'#a1aaa0':'#d2c9b7';for(let child of [...node.children]){node.remove(child);child.traverse(n=>{if(n.isMesh)n.geometry.dispose();});}sphere(node,0,1,0,.65,color,.66,.73,1.3);let head=new THREE.Group();head.position.set(0,1.54,.6);node.add(head);sphere(head,0,0,0,.33,color,.78,1,.85);sphere(head,0,-.13,.25,.19,color,.75,.6,1.1);sphere(head,0,-.1,.41,.055,'#3e493f');let ears=[];for(let side of [-1,1]){let ear=cyl(head,side*.21,.33,0,0,.1,type==='rabbit'?.65:type==='deer'?.42:.27,color,10);ear.rotation.z=side*.25;ears.push(ear);sphere(head,side*.12,.04,.27,.038,'#25362e',.7,1,.45);sphere(head,side*.125,.052,.286,.009,'#f1eadb');if(type==='deer'){let antler=cyl(head,side*.15,.5,-.08,.025,.04,.58,'#ad9c78',8);antler.rotation.z=side*.3;let tine=cyl(head,side*.24,.7,-.08,.015,.025,.24,'#ad9c78',6);tine.rotation.z=-side*.55;}}let legs=[];for(let side of [-1,1])for(let zz of [-.42,.42]){let leg=new THREE.Group();leg.position.set(side*.27,.83,zz);node.add(leg);cyl(leg,0,-.3,0,.06,.065,.65,color,10);sphere(leg,0,-.66,.045,.085,type==='deer'?'#655a4a':color,.8,.65,1.3);legs.push(leg);}let tail=new THREE.Group();tail.position.set(0,1,-.8);node.add(tail);if(type==='cat'){let curve=new THREE.CatmullRomCurve3([new THREE.Vector3(0,0,0),new THREE.Vector3(0,.3,-.3),new THREE.Vector3(.2,.7,-.4),new THREE.Vector3(.3,.9,-.25)]);tail.add(new THREE.Mesh(new THREE.TubeGeometry(curve,12,.045,6,false),mat(color)));}else sphere(tail,0,0,0,type==='rabbit'?.17:.12,'#e1d9c9');animal.elvenRig={head,ears,legs,tail};rebindElvenDetail(node,animal.interaction);}
function upgradeElvenResidences(){for(let home of citizenHomes){let group=worldCache.root.children.find(n=>n.name===home.title);if(!group||group.userData.elvenResidence)return;group.userData.elvenResidence=true;for(let child of [...group.children])if(child.isMesh&&child.geometry.type==='CylinderGeometry'&&child.geometry.parameters.radiusTop===0){group.remove(child);child.geometry.dispose();}buildReferenceRoof(group,9,4.7,8,'residence');for(let side of [-1,1]){leafCarving(group,side*1.2,2.8,4.4,.25);cyl(group,side*3.6,2.6,0,.085,.12,5.2,elvenPalette.wood,12);}leafCarving(group,0,4.25,4.38,.36);rebindElvenDetail(group,worldCache.objects.find(o=>o.node===group));}if(owlTreehouse&&!owlTreehouse.userData.elvenArchitecture){for(let n of [...owlTreehouse.children])if(n.geometry?.type==='ConeGeometry'){owlTreehouse.remove(n);n.geometry.dispose();}buildReplacementRoof(owlTreehouse,5,2.8,4,'treehouse');leafCarving(owlTreehouse,0,2.9,1.82,.28);owlTreehouse.userData.elvenArchitecture=true;rebindElvenDetail(owlTreehouse,worldCache.objects.find(o=>o.node===owlTreehouse));}}
function upgradeElvenSignsAndStalls(){for(let spot of fishingSpots){let sign=spot.node;if(sign.userData.elvenSign)continue;sign.userData.elvenSign=true;for(let side of [-1,1]){leafCarving(sign,side*1.7,2.8,.17,.26);let branch=new THREE.Mesh(new THREE.TorusGeometry(.7,.055,6,16,Math.PI),elvenMaterial(elvenPalette.wood));branch.position.set(side*1.1,3.6,0);sign.add(branch);}rebindElvenDetail(sign,spot);}worldCache.root.traverse(stall=>{if(!stall.userData.detailedMarket||stall.userData.elvenMarket)return;stall.userData.elvenMarket=true;for(let side of [-1,1]){leafCarving(stall,side*1.72,2.8,1.4,.28,elvenPalette.silver);let brace=box(stall,side*1.55,2.9,1.2,.09,1.2,.09,elvenPalette.wood);brace.rotation.z=side*.4;}leafCarving(stall,0,1.15,.87,.3,elvenPalette.bronze);rebindElvenDetail(stall,worldCache.objects.find(o=>o.node===stall));});}
