var referenceTextureCache;
function referenceShingles(){referenceTextureCache??=new Map();if(referenceTextureCache.has('blue'))return referenceTextureCache.get('blue');let cv=document.createElement('canvas');cv.width=cv.height=512;let c=cv.getContext('2d');c.fillStyle='#183a49';c.fillRect(0,0,512,512);for(let row=-1;row<9;row++)for(let col=-1;col<9;col++){let x=col*64+(row%2)*32,y=row*64;c.beginPath();c.moveTo(x,y);c.lineTo(x+64,y);c.lineTo(x+64,y+40);c.quadraticCurveTo(x+32,y+91,x,y+40);c.closePath();let gradient=c.createLinearGradient(x,y,x+64,y+75);gradient.addColorStop(0,'#638b9b');gradient.addColorStop(.4,'#386777');gradient.addColorStop(1,'#204552');c.fillStyle=gradient;c.fill();c.strokeStyle='#152f3b';c.lineWidth=2;c.stroke();c.strokeStyle='#88a5a0';c.lineWidth=1;c.beginPath();c.moveTo(x+4,y+37);c.quadraticCurveTo(x+32,y+78,x+60,y+37);c.stroke();for(let i=0;i<4;i++){c.strokeStyle='#b1c6b51a';c.beginPath();c.moveTo(x+8+i*12,y+7);c.lineTo(x+10+i*12,y+40);c.stroke();}}let tex=new THREE.CanvasTexture(cv);tex.wrapS=tex.wrapT=THREE.RepeatWrapping;tex.colorSpace=THREE.SRGBColorSpace;tex.anisotropy=4;referenceTextureCache.set('blue',tex);return tex;}
