function ensureDeepWoodland(){if(!worldCache||worldCache.deepWoodland)return;let g=new THREE.Group();g.name='Ancient woodland and flowering understory';worldCache.root.add(g);worldCache.deepWoodland=g;let prior={root,zone},trees=0,plants=0;root=g;for(let [id,[cx,cz]]of Object.entries(districtPositions)){zone=id;let wooded=['forest','forgotten','academy','library'].includes(id);for(let i=0;i<(wooded?(window.innerWidth<768?40:70):18);i++){let x=(i*23.71+7)%94-47,z=(i*17.33+3)%88-43,wx=cx+x,wz=cz+z;if(sceneryLane(x,z,8)||kingdomPathCovered(wx,wz)||blocked(wx,wz)||Math.abs(z-31)<10)continue;let near=worldCache.objects.some(o=>Math.hypot(o.x-wx,o.z-wz)<10);if(near)continue;let t=tree(wx,wz,wooded?3.1+(i%4)*.35:2.4+(i%3)*.25,i%3?'pine':'oak');t.userData.ancientWoodland=true;if(wooded&&i%2===0){let nx=wx+3,nz=wz-2;if(!sceneryLane(x+3,z-2,4)&&!kingdomPathCovered(nx,nz)&&!blocked(nx,nz)&&!worldCache.objects.some(o=>Math.hypot(o.x-nx,o.z-nz)<10)){let sapling=tree(nx,nz,1.2+(i%3)*.2,'pine');sapling.userData.woodlandSapling=true;}}if(i%3===0){for(let j=0;j<7;j++){let a=j*1.8,leaf=leafCarving(t,Math.sin(a)*.45,.6+j*.45,Math.cos(a)*.45,.16,'#82996b');leaf.rotation.y=a;if(j%2===0)sphere(t,Math.sin(a)*.48,.65+j*.45,Math.cos(a)*.48,.07,'#d3a6ba');}}trees++;}for(let i=0;i<(wooded?400:100);i++){let x=(i*13.71)%94-47,z=(i*19.17)%89-43,wx=cx+x,wz=cz+z;if(sceneryLane(x,z,1.5)||kingdomPathCovered(wx,wz)||blocked(wx,wz)||Math.abs(z-31)<5)continue;referenceMeadowFlower(g,wx,wz,i+17);plants++;if(i%5===0){let fern=new THREE.Group();fern.position.set(wx,.05,wz);fern.userData.referenceFern=true;g.add(fern);for(let j=0;j<7;j++){let a=j*Math.PI*2/7;let leaf=leafCarving(fern,Math.sin(a)*.28,.32,Math.cos(a)*.28,.44,'#82996b');leaf.rotation.set(-.75,a,.3);}plants++;}if(i%13===0){let shrub=new THREE.Group();shrub.position.set(wx,0,wz);shrub.userData.referenceFlora=true;g.add(shrub);referenceShrub(shrub,0,.65,0,.7,i);plants++;}}}
root=prior.root;zone=prior.zone;g.userData.summary={trees,plants};clearSceneryFromKingdomPaths();batchWorld(g);}
