var outdoorRestSeat=null;
function ensureWoodlandRestPlaces(){if(!worldCache||worldCache.restPlaces)return;let g=new THREE.Group();g.name='Woodland undergrowth and kingdom resting places';worldCache.root.add(g);worldCache.restPlaces=g;worldCache.restBenches=[];let prior={root,objects,zone},plants=0;root=g;objects=[];for(let [id,[cx,cz]]of Object.entries(districtPositions)){zone=id;for(let [x,z]of [[-19,18],[19,18],[-34,17],[34,17]]){let wx=cx+x,wz=cz+z;if(blocked(wx,wz)||blocked(wx,wz+2)||kingdomPathCovered(wx,wz))continue;let bench=new THREE.Group();bench.position.set(wx,0,wz);g.add(bench);for(let zz of [-.28,0,.28])box(bench,0,.87,zz,3.2,.13,.24,'#8c7757',{map:floorTex});for(let x of [-2,2]){box(bench,x,.43,0,.18,.86,.55,'#5f604c');box(bench,x,1.12,-.37,.13,1.45,.13,'#665b43');}for(let y of [1.18,1.52])box(bench,0,y,-.4,3.2,.25,.12,'#8c7757',{map:floorTex});leafCarving(bench,0,1.5,-.31,.22,'#c4d8d1');let seat={x:wx,z:wz,district:id,node:bench};worldCache.restBenches.push(seat);worldCache.colliders.push({x:wx,z:wz,w:1.65,d:.48});interactable('Sit and rest on the woodland bench',wx,wz+2,()=>{if(seated)standUp();stopTravel();outdoorRestSeat=seat;seated=true;player.group.position.set(wx,-.06,wz);player.group.rotation.y=0;animatePerson(player,elapsed,false);toast('Resting on the bench · move to stand up');},bench,2.5,'rest');}
for(let i=0;i<220;i++){let x=(i*17.67)%94-47,z=(i*23.13)%89-43,wx=cx+x,wz=cz+z;if(sceneryLane(x,z,1.7)||kingdomPathCovered(wx,wz)||blocked(wx,wz)||Math.abs(z-31)<5)continue;let plantsGroup=new THREE.Group();plantsGroup.position.set(wx,0,wz);plantsGroup.userData.referenceFlora=true;g.add(plantsGroup);if(i%3===0)referenceShrub(plantsGroup,0,.5,0,.55+(i%4)*.1,i);else for(let j=0;j<7;j++){let a=j*2.4;let weed=leafCarving(plantsGroup,Math.sin(a)*.18,.22+j%3*.08,Math.cos(a)*.18,.22+j%3*.06,i%2?'#708056':'#82996b');weed.rotation.set(-.3,a,.6);}plants++;}}
let grass=worldCache.elvenGrass,matrix=new THREE.Matrix4();for(let i=0;i<grass.count;i++){grass.getMatrixAt(i,matrix);if(blocked(matrix.elements[12],matrix.elements[14])){matrix.makeScale(0,0,0);matrix.setPosition(0,0,16);grass.setMatrixAt(i,matrix);}}grass.instanceMatrix.needsUpdate=true;worldCache.npcs.forEach((n,i)=>n.woodlandRestOrder=i);g.userData.summary={benches:worldCache.restBenches.length,plants};worldCache.objects.push(...objects);root=prior.root;objects=prior.objects;zone=prior.zone;clearSceneryFromKingdomPaths();batchWorld(g);}
const restStandBefore=standUp;standUp=function(){if(seated&&outdoorRestSeat){let seat=outdoorRestSeat;outdoorRestSeat=null;seated=false;player.group.position.set(seat.x,0,seat.z+2);animatePerson(player,elapsed,false);return;}restStandBefore();};
function citizenRestBench(n){if(room||n.isCourier||n.isContact||n.woodlandRestOrder===undefined)return null;let h=Math.floor(state.minutes/60),minute=state.minutes%60,index=n.woodlandRestOrder;if(h<10||h>=21||minute<index%4*12||minute>=index%4*12+8)return null;let offset=n.offset||{x:0,z:0},id=Object.keys(districtPositions).find(id=>districtPositions[id][0]===offset.x&&districtPositions[id][1]===offset.z),benches=worldCache.restBenches.filter(b=>b.district===id);return benches[index%benches.length]||null;}
const restingScheduleBefore=scheduleFor;scheduleFor=function(n,hour){let bench=citizenRestBench(n);if(bench){let offset=n.offset||{x:0,z:0};return{x:bench.x-offset.x,z:bench.z+2-offset.z,activity:'resting on a woodland bench',visible:true};}return restingScheduleBefore(n,hour);};
const restingResidentBefore=animateResident;animateResident=function(n,i,dt){let bench=citizenRestBench(n),offset=n.offset||{x:0,z:0};if(n.activeRestBench&&n.activeRestBench!==bench){n.group.position.set(n.activeRestBench.x-offset.x,0,n.activeRestBench.z+2-offset.z);n.scheduleKey=null;}n.activeRestBench=bench;restingResidentBefore(n,i,dt);if(bench&&!n.dayRoute?.length&&Math.hypot(n.group.position.x+offset.x-bench.x,n.group.position.z+offset.z-bench.z-2)<2.1){n.group.position.set(bench.x-offset.x,-.06,bench.z-offset.z);n.group.rotation.y=0;n.legs.forEach(p=>p.rotation.x=-Math.PI/2);n.knees.forEach(p=>p.rotation.x=Math.PI/2);n.arms.forEach(p=>p.rotation.x=-.32);let o=worldCache.objects.find(o=>o.node===n.group);if(o){o.x=bench.x;o.z=bench.z;}}};
